{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `MAPLEMONK.Freakins_GRN_Factitems` AS SELECT PO_Code, CASE WHEN PO_Date IS NOT NULL AND PO_Date <> \'\' THEN CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', PO_Date) AS DATE) ELSE NULL END AS PO_Date, PO_Type, Category, Facility, GRN_Code, CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) ELSE NULL END AS GRN_Date, Batch_Code, Vendor_Code, Vendor_Name, trim(Item_SkuCode) Item_SkuCode, GRN_Created_By, GRN_Invoice_No, Item_Type_Name, Item_Type_Size, Vendor_SkuCode, Facility Warehouse_Name, Grn_item_Status, Item_Type_Brand, Item_Type_Color, CASE WHEN GRN_Invoice_Date IS NOT NULL AND GRN_Invoice_Date <> \'\' THEN SAFE_CAST(PARSE_DATE(\'%Y-%m-%d\', GRN_Invoice_Date) AS DATE) ELSE NULL END AS GRN_Invoice_Date, Rejection_Reason, CASE WHEN Total_Quantity_Received <> \'\' THEN CAST(Total_Quantity_Received AS INT64) end AS Quantity_Received, CASE WHEN Quantity_Rejected <> \'\' THEN CAST(Quantity_Rejected AS INT64) end AS Quantity_Rejected, CASE WHEN Percentage_Rejection <> \'\' then CAST(Percentage_Rejection AS FLOAT64) end AS Percentage_Rejection, CASE WHEN Values_of_Goods_Received_with_taxes <> \'\' then CAST(Values_of_Goods_Received_with_taxes AS FLOAT64) end AS GRN_Received_Value_with_taxes, CASE WHEN Values_of_Goods_Received_without_taxes <> \'\' then CAST(Values_of_Goods_Received_without_taxes AS FLOAT64) end AS GRN_Received_Value_without_taxes, CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATETIME) ELSE NULL END AS GRN_Received_Timestamp, CASE WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY) THEN \'0-30\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 60 DAY) THEN \'30-60\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY) THEN \'60-90\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 120 DAY) THEN \'90-120\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 180 DAY) THEN \'120-180\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 270 DAY) THEN \'180-270\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 360 DAY) THEN \'270-360\' ELSE \'360+\' END AS Bucket, CASE WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) ELSE NULL END) > DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY) THEN \'0-30\' ELSE \'30+\' END AS Extra_Bucket, Putaway_Code, CASE WHEN Putaway_Created IS NOT NULL AND Putaway_Created <> \'\' THEN CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Putaway_Created) AS DATE) ELSE NULL END AS Putaway_Date, FROM maplemonk.unicommerce_get_grn_report WHERE UPPER(Facility) like any (\'%DLDRK%\',\'%BHIWANDI%\'); create or replace table maplemonk.freakins_inventory_ageing_consolidated as WITH daily_grn as ( SELECT DISTINCT c.date_day, g.item_skucode, g.category, FROM `MAPLEMONK.Freakins_GRN_Factitems` AS g CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(DATE_SUB(CURRENT_DATE(),INTERVAL 1 YEAR), YEAR), CURRENT_DATE())) AS date_day ) AS c ), GRN AS( select date(dg.date_day) as date, dg.item_skucode, dg.Category, sum(ifnull(Quantity_Received,0)) as Received_Quantity, sum(ifnull(Quantity_Rejected,0)) as Rejected_Quantity from daily_grn dg left join `MAPLEMONK.Freakins_GRN_Factitems` g on dg.date_day = cast(g.grn_date as date) and dg.item_skucode = g.item_skucode and dg.category = g.category group by 1,2,3 having sum(ifnull(Quantity_Received,0)) > 0 order by 1 desc ), grn_date_wise AS ( select date as date, date_trunc(mg.date,month) as month, mg.item_skucode, mg.Category, CASE WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 30 THEN \'0-30\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 60 THEN \'30-60\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 90 THEN \'60-90\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 120 THEN \'90-120\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 150 THEN \'120-150\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 180 THEN \'150-180\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 210 THEN \'180-210\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 240 THEN \'210-240\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 270 THEN \'240-270\' END as Inventory_Ageing_Bucket, sum(ifnull(mg.Received_Quantity,0)) - sum(ifnull(mg.Rejected_Quantity,0)) as Daily_Received_Quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 1 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w1_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 2 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w2_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 3 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w3_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 4 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w4_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 5 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w5_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 6 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w6_grn_quantity from grn mg group by 1,2,3,4,5 ), grn_total as ( select item_skucode, category, sum(ifnull(Received_Quantity,0)) - sum(ifnull(Rejected_Quantity,0)) as Total_Inwarded_Quantity from grn group by 1,2 ), grn_cummulative as ( select g.date, g.month, g.item_skucode, g.category, sum(ifnull(g1.Daily_Received_Quantity,0)) as Cummulative_Quantity from grn_date_wise g left join grn_date_wise g1 on g1.date < g.date and g1.item_skucode = g.item_skucode and g1.category = g.category group by 1,2,3,4 ), daily_sales as ( SELECT DISTINCT c.date_day, s.sku, s.Product_Category_Main as product_category, FROM `MAPLEMONK.Freakins_db_sales_consolidated` AS s CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(CURRENT_DATE(), YEAR), CURRENT_DATE())) AS date_day ) AS c ), sales AS ( select date(ds.date_day) as date, ds.sku as sku, ds.Product_Category, sum(ifnull(Quantity,0)) as Sold_Quantity from daily_sales ds left join `MAPLEMONK.Freakins_db_sales_consolidated` s on ds.date_day = cast(s.order_date as date) and lower(ds.sku) = lower(s.sku) and lower(ds.product_category) = lower(s.Product_Category_Main) group by 1,2,3 ), sales_final as ( select si.*, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 6 FOLLOWING) AS N7_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 14 FOLLOWING) AS N14_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 29 FOLLOWING) AS N30_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 44 FOLLOWING) AS N45_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 59 FOLLOWING) AS N60_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 89 FOLLOWING) AS N90_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 179 FOLLOWING) AS N180_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 359 FOLLOWING) AS N360_day_sales from sales si ), current_stock as ( SELECT Data_Fetch_Date, Sku, category, Available_Inventory FROM ( SELECT Data_Fetch_Date, UPPER(sku) SKU, category, Available_Inventory, ROW_NUMBER() OVER (PARTITION BY UPPER(Sku),category ORDER BY Data_Fetch_Date DESC) AS rw FROM maplemonk.freakins_inventory_fact_items ) WHERE rw = 1 ) select g.*, sm.style_code, sm.Product_ID, sm.Product_title, s.N7_day_sales, s.N14_day_sales, s.N30_day_sales, s.N60_day_sales, s.N90_day_sales, s.N180_day_sales, s.N360_day_sales, s.Sold_Quantity as Sold_Quantity_Daily, cs.available_inventory as Current_Stock, SUM(cs.available_inventory) OVER (PARTITION BY g.category) AS category_current_stock, SUM(cs.available_inventory) OVER (PARTITION BY sm.style_code) AS style_current_stock, gc.Cummulative_Quantity, CASE WHEN (gt.Total_Inwarded_Quantity - cs.available_inventory) < (gc.Cummulative_Quantity + g.Daily_Received_Quantity) THEN CASE WHEN gc.Cummulative_Quantity > (gt.Total_Inwarded_Quantity - cs.available_inventory) THEN g.Daily_Received_Quantity ELSE g.Daily_Received_Quantity - ((gt.Total_Inwarded_Quantity - cs.available_inventory) - gc.Cummulative_Quantity) END ELSE 0 END as Current_Ageing_Inventory from grn_date_wise g left join sales_final s on s.date = g.date and s.sku = g.item_skucode and s.product_category = g.category left join `MAPLEMONK.FREAKINS_FINALL_SKU_MASTER` sm on lower(replace(sm.variant_sku,\' \',\'\')) = lower(g.item_skucode) left join current_stock cs on lower(cs.sku) = lower(g.item_skucode) and lower(cs.category) = lower(g.category) left join grn_total gt on lower(gt.item_skucode) = lower(g.item_skucode) and lower(gt.category) = lower(g.category) left join grn_cummulative gc on lower(gc.item_skucode) = lower(g.item_skucode) and gc.date = g.date and lower(gc.category) = lower(g.category) ; create or replace table maplemonk.freakins_inventory_ageing_consolidated_putaway as WITH daily_grn as ( SELECT DISTINCT c.date_day, g.item_skucode, g.category, FROM `MAPLEMONK.Freakins_GRN_Factitems` AS g CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(DATE_SUB(CURRENT_DATE(),INTERVAL 1 YEAR), YEAR), CURRENT_DATE())) AS date_day ) AS c ), GRN AS( select date(dg.date_day) as date, dg.item_skucode, dg.Category, sum(ifnull(Quantity_Received,0)) as Received_Quantity, sum(ifnull(Quantity_Rejected,0)) as Rejected_Quantity from daily_grn dg left join `MAPLEMONK.Freakins_GRN_Factitems` g on dg.date_day = cast(g.putaway_date as date) and dg.item_skucode = g.item_skucode and dg.category = g.category group by 1,2,3 having sum(ifnull(Quantity_Received,0)) > 0 order by 1 desc ), putaway_date_wise AS ( select date as date, date_trunc(mg.date,month) as month, mg.item_skucode, mg.Category, CASE WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 30 THEN \'0-30\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 60 THEN \'30-60\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 90 THEN \'60-90\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 120 THEN \'90-120\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 150 THEN \'120-150\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 180 THEN \'150-180\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 210 THEN \'180-210\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 240 THEN \'210-240\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 270 THEN \'240-270\' END as Inventory_Ageing_Bucket, sum(ifnull(mg.Received_Quantity,0)) - sum(ifnull(mg.Rejected_Quantity,0)) as Daily_Received_Quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 1 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w1_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 2 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w2_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 3 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w3_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 4 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w4_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 5 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w5_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 6 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w6_grn_quantity from grn mg group by 1,2,3,4,5 ), putaway_total as ( select item_skucode, category, sum(ifnull(Received_Quantity,0)) - sum(ifnull(Rejected_Quantity,0)) as Total_Inwarded_Quantity from grn group by 1,2 ), putaway_cummulative as ( select g.date, g.month, g.item_skucode, g.category, sum(ifnull(g1.Daily_Received_Quantity,0)) as Cummulative_Quantity from putaway_date_wise g left join putaway_date_wise g1 on g1.date < g.date and g1.item_skucode = g.item_skucode and g1.category = g.category group by 1,2,3,4 ), putaway_cummulative_incl as ( select g.date, g.month, g.item_skucode, g.category, sum(ifnull(g1.Daily_Received_Quantity,0)) as Incl_Cummulative_Quantity from putaway_date_wise g left join putaway_date_wise g1 on g1.date <= g.date and g1.item_skucode = g.item_skucode and g1.category = g.category group by 1,2,3,4 ), daily_sales as ( SELECT DISTINCT c.date_day, s.sku, s.Product_Category_Main as product_category, FROM `MAPLEMONK.Freakins_db_sales_consolidated` AS s CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(CURRENT_DATE(), YEAR), CURRENT_DATE())) AS date_day ) AS c ), sales AS ( select date(ds.date_day) as date, ds.sku as sku, ds.Product_Category, sum(ifnull(Quantity,0)) as Sold_Quantity from daily_sales ds left join `MAPLEMONK.Freakins_db_sales_consolidated` s on ds.date_day = cast(s.order_date as date) and lower(ds.sku) = lower(s.sku) and lower(ds.product_category) = lower(s.Product_Category_Main) group by 1,2,3 ), sales_final as ( select si.*, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 6 FOLLOWING) AS N7_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 14 FOLLOWING) AS N14_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 29 FOLLOWING) AS N30_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 44 FOLLOWING) AS N45_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 59 FOLLOWING) AS N60_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 89 FOLLOWING) AS N90_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 179 FOLLOWING) AS N180_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 359 FOLLOWING) AS N360_day_sales from sales si ), sales_cummulative as ( select s.date, s.sku, s.Product_Category, sum(ifnull(s1.N7_day_sales,0)) as N7_cummulative_sales, sum(ifnull(s1.N14_day_sales,0)) as N14_cummulative_sales, sum(ifnull(s1.N30_day_sales,0)) as N30_cummulative_sales, sum(ifnull(s1.N45_day_sales,0)) as N45_cummulative_sales, sum(ifnull(s1.N60_day_sales,0)) as N60_cummulative_sales, sum(ifnull(s1.N90_day_sales,0)) as N90_cummulative_sales, sum(ifnull(s1.N180_day_sales,0)) as N180_cummulative_sales, sum(ifnull(s1.N360_day_sales,0)) as N360_cummulative_sales from (select * from sales_final where concat(date,lower(sku),lower(product_category)) in (select concat(date,lower(item_skucode),lower(category)) from putaway_date_wise) ) s left join (select * from sales_final where concat(date,lower(sku),lower(product_category)) in (select concat(date,lower(item_skucode),lower(category)) from putaway_date_wise)) s1 on s1.date <= s.date and s1.sku = s.sku and s1.Product_Category = s.Product_Category group by 1,2,3 ), current_stock as ( SELECT Data_Fetch_Date, Sku, category, Available_Inventory FROM ( SELECT Data_Fetch_Date, UPPER(sku) SKU, category, Available_Inventory, ROW_NUMBER() OVER (PARTITION BY UPPER(Sku),category ORDER BY Data_Fetch_Date DESC) AS rw FROM maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS ) WHERE rw = 1 ) select g.*, sm.style_code, sm.Product_ID, sm.Product_title, s.N7_day_sales, s.N14_day_sales, s.N30_day_sales, s.N60_day_sales, s.N90_day_sales, s.N180_day_sales, s.N360_day_sales, s.Sold_Quantity as Sold_Quantity_Daily, cs.available_inventory as Current_Stock, g.Daily_Received_Quantity - (gcl.Incl_Cummulative_Quantity - sc.N30_cummulative_sales) as N30_Sales, SUM(cs.available_inventory) OVER (PARTITION BY g.category) AS category_current_stock, SUM(cs.available_inventory) OVER (PARTITION BY sm.style_code) AS style_current_stock, gc.Cummulative_Quantity, sc.N30_cummulative_sales, sc.N60_cummulative_sales, sc.N90_cummulative_sales, CASE WHEN (gt.Total_Inwarded_Quantity - cs.available_inventory) < (gc.Cummulative_Quantity + g.Daily_Received_Quantity) THEN CASE WHEN gc.Cummulative_Quantity > (gt.Total_Inwarded_Quantity - cs.available_inventory) THEN g.Daily_Received_Quantity ELSE g.Daily_Received_Quantity - ((gt.Total_Inwarded_Quantity - cs.available_inventory) - gc.Cummulative_Quantity) END ELSE 0 END as Current_Ageing_Inventory from putaway_date_wise g left join sales_final s on s.date = g.date and s.sku = g.item_skucode and s.product_category = g.category left join `MAPLEMONK.FREAKINS_FINALL_SKU_MASTER` sm on lower(replace(sm.variant_sku,\' \',\'\')) = lower(g.item_skucode) left join current_stock cs on lower(cs.sku) = lower(g.item_skucode) and lower(cs.category) = lower(g.category) left join putaway_total gt on lower(gt.item_skucode) = lower(g.item_skucode) and lower(gt.category) = lower(g.category) left join putaway_cummulative gc on lower(gc.item_skucode) = lower(g.item_skucode) and gc.date = g.date and lower(gc.category) = lower(g.category) left join putaway_cummulative_incl gcl on lower(gcl.item_skucode) = lower(g.item_skucode) and gcl.date = g.date and lower(gcl.category) = lower(g.category) left join sales_cummulative sc on lower(sc.sku) = lower(g.item_skucode) and sc.date = g.date and lower(sc.product_category) = lower(g.category) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            